const rawSignals = $('Read raw_signals').all().map((it) => it.json || {});
const normalizedRows = $('Read normalized_terms').all().map((it) => it.json || {});
const existingRows = $('Read marketplace_evidence').all().map((it) => it.json || {}).filter((row) => String(row.evidence_id || '').trim());
const existing = new Set(
  existingRows.map((row) => String(row.evidence_id || '').trim()).filter(Boolean),
);

function slugify(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 80);
}

function normalizeText(text) {
  return String(text || '').replace(/\s+/g, ' ').trim();
}

const canonicalMap = new Map();
for (const row of normalizedRows) {
  const canonicalId = String(row.canonical_id || '').trim();
  if (!canonicalId) continue;
  const canonicalTerm = normalizeText(row.canonical_term || canonicalId.replace(/^norm_/, ''));
  canonicalMap.set(canonicalTerm.toLowerCase(), canonicalId);
  const aliases = normalizeText(row.aliases);
  if (aliases) {
    for (const alias of aliases.split('|')) {
      const key = normalizeText(alias).toLowerCase();
      if (key) canonicalMap.set(key, canonicalId);
    }
  }
}

function resolveCanonicalId(term) {
  const key = normalizeText(term).toLowerCase();
  return canonicalMap.get(key) || null;
}

const out = [];
for (const raw of rawSignals) {
  const signalId = String(raw.signal_id || '').trim();
  const term = normalizeText(raw.term);
  if (!term || signalId === 'ERROR' || term.toLowerCase() === 'fetch_failed') continue;

  const canonicalId = resolveCanonicalId(term);
  if (!canonicalId) continue;

  const source = normalizeText(raw.source);
  const evidenceId = 'ev_' + slugify(signalId || term);
  if (existing.has(evidenceId)) continue;

  out.push({
    json: {
      evidence_id: evidenceId,
      canonical_id: canonicalId,
      source: source || 'unknown',
      phrase: term,
      product_type: source === 'etsy_autocomplete' ? 't-shirt|mug|sticker' : 't-shirt|sticker',
      intent_type: source === 'etsy_autocomplete' ? 'buyer_intent' : 'trend_interest',
      evidence_strength: source === 'etsy_autocomplete' ? 0.9 : 0.55,
      captured_at: normalizeText(raw.date_collected) || new Date().toISOString(),
    },
  });
}

if (!out.length) {
  const now = new Date().toISOString();
  return [
    {
      json: {
        __noRows: true,
        run_id: 'run_wf_enrich_marketplace_' + Date.now(),
        run_started: now,
        run_finished: now,
        job_name: 'wf_enrich_marketplace',
        rows_added: 0,
        rows_updated: 0,
        status: 'success',
        error_log: '',
      },
    },
  ];
}

return out;

