const input = $input.first().json;
const inputMarket = input.market ?? 'UK';
const geo = inputMarket === 'UK' ? 'GB' : String(inputMarket).toUpperCase();
const hl = geo === 'GB' ? 'en-GB' : 'en-US';
const outMarketLabel = geo === 'GB' ? 'UK' : geo;
const helpers = this.helpers;

function slugify(text) {
  return String(text)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 80);
}

function decodeXmlEntities(text) {
  return String(text || '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'");
}

function stripTags(text) {
  return decodeXmlEntities(String(text || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
}

function extractTraffic(block) {
  const m = String(block).match(/<ht:approx_traffic>([\s\S]*?)<\/ht:approx_traffic>/i);
  return m ? stripTags(m[1]) : '';
}

function extractTitle(block) {
  const m = String(block).match(/<title>([\s\S]*?)<\/title>/i);
  return m ? stripTags(m[1]) : '';
}

function extractRelated(block) {
  const related = [];
  const matches = String(block).matchAll(/<a[^>]*>([\s\S]*?)<\/a>/gi);
  for (const match of matches) {
    const text = stripTags(match[1]);
    if (text) related.push(text);
  }
  return related;
}

function buildRow(title, related, traffic) {
  const slug = slugify(title) || 'unknown';
  return {
    json: {
      signal_id: 'sig_google_' + new Date().toISOString().slice(0, 10) + '_' + slug,
      date_collected: new Date().toISOString(),
      source: 'google_trends',
      market: outMarketLabel,
      term: title,
      related_term: (Array.isArray(related) ? related : []).slice(0, 5).join(' | '),
      category: 'general',
      signal_type: 'rising_query',
      velocity_hint: traffic || 'medium',
      url: 'https://trends.google.com/trending?geo=' + encodeURIComponent(geo),
      raw_payload_json: JSON.stringify({ title, related, traffic }),
    },
  };
}

const baseHeaders = {
  Accept: 'application/rss+xml, text/xml, */*',
  'Accept-Language': hl + ',en;q=0.8',
  'User-Agent': 'Mozilla/5.0 (compatible; n8n-trends-bot/1.0; +https://example.invalid)',
};

async function fetchRss() {
  const url = 'https://trends.google.com/trending/rss?geo=' + encodeURIComponent(geo) + '&safe=active';
  const bodyText = await helpers.httpRequest({
    method: 'GET',
    url,
    headers: baseHeaders,
    returnFullResponse: false,
    json: false,
  });
  const xml = String(bodyText || '');
  const itemBlocks = xml.match(/<item>[\s\S]*?<\/item>/gi) || [];
  return itemBlocks
    .slice(0, 20)
    .map((block) => {
      const title = extractTitle(block);
      const related = extractRelated(block);
      const traffic = extractTraffic(block);
      return buildRow(title, related, traffic);
    })
    .filter((r) => r.json.term);
}

async function fetchDailytrendsJson() {
  const url =
    'https://trends.google.com/trends/api/dailytrends?hl=' +
    encodeURIComponent(hl) +
    '&tz=0&geo=' +
    encodeURIComponent(geo) +
    '&ns=15';
  const bodyText = await helpers.httpRequest({
    method: 'GET',
    url,
    headers: { ...baseHeaders, Accept: 'application/json, text/plain, */*' },
    returnFullResponse: false,
    json: false,
  });
  let text = String(bodyText || '');
  text = text.replace(/^\)\]\}',?\s*/, '');
  let data;
  try {
    data = JSON.parse(text);
  } catch (_pe) {
    return [];
  }
  const days = (data && data.default && data.default.trendingSearchesDays) || [];
  const rows = [];
  for (const day of days) {
    const trends = Array.isArray(day && day.trendingSearches) ? day.trendingSearches : [];
    for (const t of trends) {
      const title = String((t && t.title && t.title.query) || '').trim();
      if (!title) continue;
      const related = (Array.isArray(t && t.relatedQueries) ? t.relatedQueries : [])
        .map((r) => String((r && r.query) || ''))
        .filter(Boolean);
      const traffic = String((t && t.formattedTraffic) || '').trim();
      rows.push(buildRow(title, related, traffic));
    }
  }
  return rows;
}

try {
  let rows = [];
  try {
    rows = await fetchRss();
  } catch (_e1) {
    rows = [];
  }
  if (!rows.length) {
    try {
      rows = await fetchDailytrendsJson();
    } catch (_e2) {
      rows = [];
    }
  }
  return rows;
} catch (err) {
  const msg = (err && err.message) || String(err);
  return [
    {
      json: {
        signal_id: 'ERROR',
        source: 'google_trends',
        term: 'fetch_failed',
        date_collected: new Date().toISOString(),
        raw_payload_json: msg,
      },
    },
  ];
}

const SEEDS = [
  'pickleball','stanley cup','cottagecore','dark academia','granola girl',
  'coastal grandmother','that girl','mob wife','quiet luxury','coquette',
];
const dateStamp = new Date().toISOString().slice(0, 10);
const dateCollected = new Date().toISOString();
const helpers = this.helpers;

function slugify(text) {
  return String(text).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80);
}
function dedupeKey(p) { return String(p).trim().toLowerCase(); }
function delay(ms) { return new Promise((r) => setTimeout(r, ms)); }

function extractPhrases(payload) {
  if (!payload) return [];
  if (Array.isArray(payload)) {
    return payload
      .map((x) =>
        typeof x === 'string'
          ? x
          : (x && (x.query ?? x.title ?? x.text ?? x.value ?? x.suggestion ?? x.name ?? x.phrase)) || ''
      )
      .filter(Boolean);
  }
  if (typeof payload !== 'object') return [];
  const buckets = [
    payload.results,
    payload.suggestions,
    payload.data,
    payload.prefixes,
    payload.autocomplete,
    payload.items,
    payload.related,
  ].filter(Array.isArray);
  for (const arr of buckets) {
    const out = extractPhrases(arr);
    if (out.length) return out;
  }
  return [];
}

const UAS = [
  'Mozilla/5.0 (Macintosh; Intel Mac OS X 14_4) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
  'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
];
function pickUA() { return UAS[Math.floor(Math.random() * UAS.length)]; }

async function tryFetch(url, jsonExpected, extraHeaders) {
  const headers = {
    Accept: 'application/json, text/plain, */*',
    'Accept-Language': 'en-GB,en;q=0.8',
    Referer: 'https://www.etsy.com/',
    'User-Agent': pickUA(),
    ...(extraHeaders || {}),
  };
  const res = await helpers.httpRequest({ method: 'GET', url, headers, json: jsonExpected });
  return res;
}

async function fetchSuggestions(seed) {
  // Primary Etsy API endpoint.
  try {
    const url = 'https://www.etsy.com/api/v3/ajax/autocomplete/prefix?q=' + encodeURIComponent(seed) + '&limit=10';
    const res = await tryFetch(url, true);
    const phrases = extractPhrases(res);
    if (phrases.length) return { phrases, via: 'etsy_v3_prefix' };
  } catch (_e1) {}

  // Secondary Etsy endpoint.
  try {
    const url2 = 'https://www.etsy.com/suggestions_ajax.php?search_query=' + encodeURIComponent(seed);
    const raw = await tryFetch(url2, false);
    let body = raw;
    if (typeof body === 'string') {
      try { body = JSON.parse(body); } catch (_pe) { body = null; }
    }
    const phrases = extractPhrases(body);
    if (phrases.length) return { phrases, via: 'etsy_suggestions_ajax' };
  } catch (_e2) {}

  // Reliability fallback: DuckDuckGo autocomplete (public, no key).
  try {
    const url3 = 'https://duckduckgo.com/ac/?q=' + encodeURIComponent(seed) + '&type=list';
    const res3 = await tryFetch(url3, true, { Referer: 'https://duckduckgo.com/' });
    const phrases = extractPhrases(res3);
    if (phrases.length) return { phrases, via: 'duckduckgo_ac_fallback' };
  } catch (_e3) {}

  return { phrases: null, via: 'none' };
}

const seen = new Map();
const out = [];

for (let i = 0; i < SEEDS.length; i++) {
  if (i > 0) await delay(500);
  const seedTerm = SEEDS[i];
  const result = await fetchSuggestions(seedTerm);
  const phrases = result.phrases;

  if (phrases === null) {
    out.push({
      json: {
        signal_id: 'ERROR',
        source: 'etsy_autocomplete',
        term: 'fetch_failed',
        date_collected: dateCollected,
        related_term: seedTerm,
        raw_payload_json: JSON.stringify({ seed: seedTerm, error: 'all endpoints failed', via: result.via }),
      },
    });
    continue;
  }

  for (const phrase of phrases) {
    const key = dedupeKey(phrase);
    if (!key || seen.has(key)) continue;
    seen.set(key, true);
    const slug = slugify(phrase) || 'unknown';
    out.push({
      json: {
        signal_id: 'sig_etsy_' + dateStamp + '_' + slug,
        date_collected: dateCollected,
        source: 'etsy_autocomplete',
        market: 'UK',
        term: phrase,
        related_term: seedTerm,
        category: 'marketplace_phrase',
        signal_type: 'buyer_intent',
        velocity_hint: result.via === 'duckduckgo_ac_fallback' ? 'fallback' : 'unknown',
        url: 'https://www.etsy.com/search?q=' + encodeURIComponent(phrase),
        raw_payload_json: JSON.stringify({ seed: seedTerm, suggestion: phrase, via: result.via }),
      },
    });
  }
}

return out;

const SEEDS = [
  'pickleball','stanley cup','cottagecore','dark academia','granola girl',
  'coastal grandmother','that girl','mob wife','quiet luxury','coquette',
];
const dateStamp = new Date().toISOString().slice(0, 10);
const dateCollected = new Date().toISOString();
const helpers = this.helpers;

function slugify(text) {
  return String(text).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80);
}
function dedupeKey(p) { return String(p).trim().toLowerCase(); }
function delay(ms) { return new Promise((r) => setTimeout(r, ms)); }

function isLikelySuggestion(v) {
  const s = String(v || '').trim();
  if (!s || s.length < 3 || s.length > 60) return false;
  if (/[:{}<>]/.test(s)) return false;
  if (/\b(middleware|responder|resource|provider|wrapper|request|parser|loader|cookieparser|sessionparser|csrfrequest)\b/i.test(s)) return false;
  if (/^[a-z]+(?:[A-Z][a-z0-9]+)+$/.test(s)) return false;
  if (/^[^\s]+$/.test(s) && /[A-Z]/.test(s)) return false;
  return true;
}

function collectFromArray(arr) {
  return (Array.isArray(arr) ? arr : [])
    .map((x) => typeof x === 'string' ? x : (x && (x.display_name ?? x.query ?? x.term ?? x.phrase ?? x.suggestion ?? x.name)) || '')
    .map((x) => String(x || '').replace(/\u([0-9a-fA-F]{4})/g, (_, h) => String.fromCharCode(parseInt(h, 16))).trim())
    .filter(isLikelySuggestion);
}

function extractPhrases(payload) {
  if (!payload || typeof payload !== 'object') return [];
  const rr = payload.resource_response || {};
  const primary = collectFromArray(rr.data);
  if (primary.length) return primary;
  const fallbackBuckets = [payload.results, payload.suggestions, payload.terms, payload.items, payload.recommended_terms, payload.data];
  for (const b of fallbackBuckets) {
    const out = collectFromArray(b);
    if (out.length) return out;
  }
  return [];
}

function extractPhrasesFromHtml(html) {
  const text = String(html || '');
  const out = [];
  const patterns = [
    /"display_name"\s*:\s*"([^"]+)"/g,
    /"name"\s*:\s*"([^"]+)"/g,
    /"query"\s*:\s*"([^"]+)"/g,
  ];
  for (const re of patterns) {
    let m;
    while ((m = re.exec(text)) !== null) {
      const v = String(m[1] || '').replace(/\u([0-9a-fA-F]{4})/g, (_, h) => String.fromCharCode(parseInt(h, 16)));
      if (isLikelySuggestion(v)) out.push(v);
    }
  }
  return out;
}

const UA =
  'Mozilla/5.0 (Macintosh; Intel Mac OS X 14_4) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36';

async function fetchTypeahead(seed) {
  const headers = {
    Accept: 'application/json, text/javascript, */*; q=0.01',
    'Accept-Language': 'en-GB,en;q=0.8',
    Referer: 'https://www.pinterest.com/',
    'User-Agent': UA,
    'X-Requested-With': 'XMLHttpRequest',
  };

  // Primary endpoint + JSON parser.
  try {
    const data = encodeURIComponent(JSON.stringify({ options: { pin_scope: 'pins', term: seed }, context: {} }));
    const url = 'https://www.pinterest.com/resource/UserSearchTypeaheadResource/get/?source_url=%2Fideas%2F&data=' + data + '&_=' + Date.now();
    const res = await helpers.httpRequest({ method: 'GET', url, headers, json: true });
    const phrases = extractPhrases(res);
    if (phrases.length) return { phrases, via: 'pinterest_typeahead_json' };
  } catch (_e1) {}

  // Secondary endpoint/parser path: HTML autocomplete page + regex extraction.
  try {
    const url2 = 'https://www.pinterest.com/search/autocomplete/?q=' + encodeURIComponent(seed);
    const html = await helpers.httpRequest({ method: 'GET', url: url2, headers: { ...headers, Accept: 'text/html, */*; q=0.1' }, json: false });
    const phrases = extractPhrasesFromHtml(html);
    if (phrases.length) return { phrases, via: 'pinterest_autocomplete_html' };
  } catch (_e2) {}

  // Reliability fallback: DuckDuckGo autocomplete (public, no key).
  try {
    const url3 = 'https://duckduckgo.com/ac/?q=' + encodeURIComponent(seed) + '&type=list';
    const ddg = await helpers.httpRequest({
      method: 'GET',
      url: url3,
      headers: { Accept: 'application/json, text/plain, */*', Referer: 'https://duckduckgo.com/', 'User-Agent': UA },
      json: true,
    });
    const phrases = extractPhrases(ddg);
    if (phrases.length) return { phrases, via: 'duckduckgo_ac_fallback' };
  } catch (_e3) {}

  return { phrases: null, via: 'none' };
}

const seen = new Map();
const out = [];

for (let i = 0; i < SEEDS.length; i++) {
  if (i > 0) await delay(500);
  const seed = SEEDS[i];
  const result = await fetchTypeahead(seed);
  const phrases = result.phrases;

  if (phrases === null) {
    out.push({
      json: {
        signal_id: 'ERROR',
        source: 'pinterest_trends',
        term: 'fetch_failed',
        date_collected: dateCollected,
        related_term: seed,
        raw_payload_json: JSON.stringify({ seed, error: 'pinterest endpoints failed', via: result.via }),
      },
    });
    continue;
  }

  for (const phrase of phrases) {
    if (!isLikelySuggestion(phrase)) continue;
    const key = dedupeKey(phrase);
    if (!key || seen.has(key)) continue;
    seen.set(key, true);
    const slug = slugify(phrase) || 'unknown';
    out.push({
      json: {
        signal_id: 'sig_pinterest_' + dateStamp + '_' + slug,
        date_collected: dateCollected,
        source: 'pinterest_trends',
        market: 'UK',
        term: phrase,
        related_term: seed,
        category: 'visual_inspiration',
