];
function pickUA() { return UAS[Math.floor(Math.random() * UAS.length)]; }

async function tryFetch(url, jsonExpected, extraHeaders) {
  const headers = {
    Accept: 'application/json, text/plain, */*',
    'Accept-Language': 'en-GB,en;q=0.8',
    Referer: 'https://www.etsy.com/',
    'User-Agent': pickUA(),
    ...(extraHeaders || {}),
  };
  const res = await helpers.httpRequest({ method: 'GET', url, headers, json: jsonExpected });
  return res;
}

async function fetchSuggestions(seed) {
  // Primary Etsy API endpoint.
  try {
    const url = 'https://www.etsy.com/api/v3/ajax/autocomplete/prefix?q=' + encodeURIComponent(seed) + '&limit=10';
    const res = await tryFetch(url, true);
    const phrases = extractPhrases(res);
    if (phrases.length) return { phrases, via: 'etsy_v3_prefix' };
  } catch (_e1) {}

  // Secondary Etsy endpoint.
  try {
    const url2 = 'https://www.etsy.com/suggestions_ajax.php?search_query=' + encodeURIComponent(seed);
    const raw = await tryFetch(url2, false);
    let body = raw;
    if (typeof body === 'string') {
      try { body = JSON.parse(body); } catch (_pe) { body = null; }
    }
    const phrases = extractPhrases(body);
    if (phrases.length) return { phrases, via: 'etsy_suggestions_ajax' };
  } catch (_e2) {}

  // Reliability fallback: DuckDuckGo autocomplete (public, no key).
  try {
    const url3 = 'https://duckduckgo.com/ac/?q=' + encodeURIComponent(seed) + '&type=list';
    const res3 = await tryFetch(url3, true, { Referer: 'https://duckduckgo.com/' });
    const phrases = extractPhrases(res3);
    if (phrases.length) return { phrases, via: 'duckduckgo_ac_fallback' };
  } catch (_e3) {}

  return { phrases: null, via: 'none' };
}

