// Inlined from sourceContractValidator.js.

const REQUIRED = ['signal_id', 'source', 'term', 'date_collected', 'raw_payload_json'];
const OPTIONAL = ['market', 'related_term', 'category', 'signal_type', 'velocity_hint', 'url'];

function validateRow(row) {
  const reasons = [];
  if (!row || typeof row !== 'object') return { ok: false, reasons: ['row_not_object'] };
  const out = {};
  for (const f of REQUIRED) {
    const v = row[f];
    if (v == null || String(v).trim() === '') { reasons.push('missing:' + f); continue; }
    out[f] = String(v).trim();
  }
  if (out.signal_id === 'ERROR' || (out.term && out.term.toLowerCase() === 'fetch_failed')) {
    return { ok: false, reasons: ['sentinel_error_row'] };
  }
  if (out.date_collected) {
    const ts = Date.parse(out.date_collected);
    if (!Number.isFinite(ts)) reasons.push('invalid:date_collected');
  }
  if (out.raw_payload_json) {
    try { JSON.parse(out.raw_payload_json); } catch (_e) {
      if (String(out.raw_payload_json).length > 4000) reasons.push('invalid:raw_payload_json_too_long');
    }
  }
  for (const f of OPTIONAL) if (row[f] != null) out[f] = String(row[f]).trim();
  if (out.term && out.term.length > 200) reasons.push('invalid:term_too_long');
  if (out.signal_id && out.signal_id.length > 200) reasons.push('invalid:signal_id_too_long');
  return { ok: reasons.length === 0, reasons, normalized: out };
}

