function isoDate(ts) { return new Date(ts).toISOString().slice(0, 10); }
function num(v) { const n = Number(v); return Number.isFinite(n) ? n : 0; }
function round2(v) { return Math.round(v * 100) / 100; }
function hash(s) { let h = 0; const x = String(s || ''); for (let i = 0; i < x.length; i++) { h = (h << 5) - h + x.charCodeAt(i); h |= 0; } return Math.abs(h).toString(36); }
function looksLikeJunk(term) {
  const t = String(term || '').trim();
  if (!t || t.length < 3 || t.length > 60) return true;
  if (/[A-Z]/.test(t) && !/\s/.test(t)) return true;
  if (/[:{}<>]/.test(t)) return true;
  if (/\b(middleware|responder|resource|provider|wrapper|request|parser|loader|cookieparser|sessionparser|csrfrequest)\b/i.test(t)) return true;
  return false;
}

function confidenceFor(group, candidate) {
  const a = String(candidate || '').toLowerCase();
  const b = String(group.term || '').toLowerCase();
  if (!a || !b) return 0;
  if (a === b) return 1;
  const ta = new Set(a.split(/\s+/).filter(Boolean));
  const tb = new Set(b.split(/\s+/).filter(Boolean));
  const inter = [...ta].filter((t) => tb.has(t)).length;
  const union = new Set([...ta, ...tb]).size || 1;
  const j = inter / union;
  const lp = a.length < 4 ? 0.5 : 1;
  return Math.min(1, j * lp + (j >= 0.5 ? 0.1 : 0));
}

function logRow(input) {
  const i = input || {};
  return {
    log_id: 'norm_' + (i.canonical_id || 'noid') + '_' + hash(i.input_term || '') + '_' + Date.now() + '_' + Math.floor(Math.random() * 1e6),
    run_id: i.run_id || '',
    run_date: i.run_date || '',
    canonical_id: i.canonical_id || '',
    input_term: i.input_term || '',
    decision_type: i.decision_type || '',
    confidence: round2(num(i.confidence)),
    merged_into: i.merged_into || '',
    reason: i.reason || '',
    created_at: new Date().toISOString(),
  };
}

