const groups = new Map();
const logRows = [];
const watchRows = [];
const stats = { created: 0, merged: 0, skipped: 0, low_confidence: 0, duplicates: 0 };

for (const raw of rawSignals) {
  const signalId = String(raw.signal_id || '').trim();
  const term = normalizeText(raw.term);
  if (looksLikeJunk(term)) {
    logRows.push(logRow({ run_id: runId, run_date: runDate, canonical_id: '', input_term: term || raw.term, decision_type: 'skipped', confidence: 0, reason: 'low_quality_term' }));
    stats.skipped += 1;
    continue;
  }
  if (!term || signalId === 'ERROR' || term.toLowerCase() === 'fetch_failed') {
    logRows.push(logRow({ run_id: runId, run_date: runDate, canonical_id: '', input_term: term || raw.term, decision_type: 'skipped', confidence: 0, reason: 'invalid_or_sentinel' }));
    stats.skipped += 1;
    continue;
  }
  const canonicalId = 'norm_' + slugify(term);
  if (existing.has(canonicalId)) {
    stats.duplicates += 1;
    logRows.push(logRow({ run_id: runId, run_date: runDate, canonical_id: canonicalId, input_term: term, decision_type: 'skipped', confidence: 1, merged_into: canonicalId, reason: 'already_canonical' }));
    continue;
  }
  const collectedAt = normalizeText(raw.date_collected) || new Date().toISOString();
  const collectedTs = parseDate(collectedAt);
  const market = normalizeText(raw.market) || 'UK';
  const category = normalizeText(raw.category || raw.source || 'general') || 'general';

  let group = groups.get(canonicalId);
  const isNew = !group;
  if (isNew) {
    group = { canonicalId, term, firstTs: collectedTs, lastTs: collectedTs, aliases: new Set([term]), markets: new Set(), categoryCounts: new Map() };
    groups.set(canonicalId, group);
  }
  group.firstTs = Math.min(group.firstTs, collectedTs);
  group.lastTs = Math.max(group.lastTs, collectedTs);
  group.aliases.add(term);
  const related = normalizeText(raw.related_term);
  if (related) {
    for (const part of related.split('|')) {
      const alias = normalizeText(part);
      if (alias) group.aliases.add(alias);
    }
  }
  group.markets.add(market);
  group.categoryCounts.set(category, (group.categoryCounts.get(category) || 0) + 1);

  const conf = confidenceFor(group, term);
  const decisionType = isNew ? 'created' : 'merged';
  logRows.push(logRow({ run_id: runId, run_date: runDate, canonical_id: canonicalId, input_term: term, decision_type: decisionType, confidence: conf, merged_into: isNew ? '' : canonicalId, reason: isNew ? 'new_canonical_term' : 'alias_into_existing_group' }));
  if (isNew) stats.created += 1; else stats.merged += 1;

  if (decisionType === 'merged' && conf < LOW_CONFIDENCE_THRESHOLD) {
    stats.low_confidence += 1;
    logRows.push(logRow({ run_id: runId, run_date: runDate, canonical_id: canonicalId, input_term: term, decision_type: 'low_confidence', confidence: conf, merged_into: canonicalId, reason: 'merge_below_threshold' }));
    watchRows.push({
      watch_id: 'watch_norm_' + canonicalId + '_' + Date.now() + '_' + Math.floor(Math.random() * 1e6),
      canonical_id: canonicalId,
      reason: 'normalization_low_confidence',
      review_after: runDate,
      notes: 'Auto-flagged: alias \'' + term + '\' merged at confidence ' + conf.toFixed(2),
    });
  }
}

