const VELOCITY_RANK={low:1,medium:2,high:3};
const str=v=>String(v==null?'':v).trim(); const num=v=>{const n=Number(v);return Number.isFinite(n)?n:0}; const arr=v=>Array.isArray(v)?v:[]; const clamp=(v,l,h)=>Math.max(l,Math.min(h,v)); const toBool=v=>v===true||String(v).toLowerCase()==='true';
const splitPipe=v=>str(v).split('|').map(s=>s.trim()).filter(Boolean);
const wordCount=t=>str(t).split(/\s+/).filter(Boolean).length;
function tokenize(h){ return String(h||'').toLowerCase().replace(/[^a-z0-9\s]+/g,' ').split(/\s+/).filter(Boolean); }
function firstMatch(h, terms){ const tk = new Set(tokenize(h)); for(const t of terms){ if(tk.has(String(t).toLowerCase())) return t; } return ''; }
function hasAny(h, terms){ return !!firstMatch(h,terms);}
function parseDate(v){ const d=new Date(v); return Number.isFinite(d.getTime())?d:null; }
function daysSince(v){ const d=parseDate(v); if(!d) return 0; return Math.max(0,Math.floor((Date.now()-d.getTime())/86400000)); }
function highestVelocity(rows){ let top='low'; for(const r of rows){ const v=str(r.velocity_hint).toLowerCase(); if(VELOCITY_RANK[v]&&VELOCITY_RANK[v]>VELOCITY_RANK[top]) top=v;} return top; }
function distinctSignalDays(rows){ const s=new Set(); for(const r of rows){ const d=parseDate(r.date_collected); if(d) s.add(d.toISOString().slice(0,10)); } return s.size; }
function deriveRisk(k){ const tk = new Set(tokenize(k)); const flags=[]; for(const t of BRAND_CELEB_RISK_WORDS){ if(tk.has(String(t).toLowerCase())) flags.push(t);} if(flags.length) return {level:'high',flags:[...new Set(flags)]}; for(const t of NEWS_EVENT_RISK_WORDS){ if(tk.has(String(t).toLowerCase())) flags.push(t);} if(flags.length) return {level:'moderate',flags:[...new Set(flags)]}; return {level:'low',flags:[]}; }
function buildCandidateOpportunity(canonicalRow, signalRows, evidenceRows){
  const c=canonicalRow||{}, signals=arr(signalRows), evidence=arr(evidenceRows); const keyword=str(c.canonical_term); const k=keyword.toLowerCase();
  const target=firstMatch(k,IDENTITY_WORDS)||'general'; const hasIdentity=target!=='general'; const hasOccasion=hasAny(k,OCCASION_WORDS);
  const signalSources=new Set(signals.map(r=>str(r.source).toLowerCase()).filter(Boolean));
  const etsyRows=evidence.filter(r=>str(r.source).toLowerCase()==='etsy_autocomplete'); const risk=deriveRisk(k);
  const product_formats=['tshirt','mug','sticker']; if(hasOccasion) product_formats.push('tote_bag'); if(hasIdentity) product_formats.push('sweatshirt'); if(hasOccasion&&wordCount(keyword)<=5) product_formats.push('greeting_card');
  const related=[]; for(const s of signals){ related.push(...splitPipe(s.related_term),...splitPipe(s.related_terms)); }
  const alias_count=splitPipe(c.aliases).length; const days_first=daysSince(c.date_first_seen); const seasonality_flag=hasOccasion?'seasonal':(alias_count>=3&&days_first>=14?'evergreen':'unknown');
  return {
    canonical_id:str(c.canonical_id), niche_keyword:keyword, target_audience:target, theme:str(c.primary_category)||'unknown', language:str(c.language)||'unknown',
